select p.post_no, title, p.member_uuid, name, post_like, reg_date from post p join member m on p.member_uuid = m.member_uuid
join post_brand pb on p.post_no = pb.post_no
join post_taste pt on p.post_no = pt.post_no
join post_ingredient pi on p.post_no = pi.post_no
left join (select avg(star) as star, post_no from star group by post_no) s on s.post_no = p.post_no
p.state=1
